// Host side of the Metal particle push (see metal_push.h and advance_p.metal).

#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

#include "metal_push.h"
#include "vpic_metal_kernels.h"  // generated by CMake from src/metal/*.metal

#include <mach/mach_time.h>
#include <unistd.h>
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <map>
#include <string>
#include <utility>
#include <vector>

namespace {

// Must match PushParams in advance_p.metal (8-byte members first)
struct vpic_metal_push_params {
  uint64_t np, stride, max_nm, first;
  int64_t  rangel, rangeh;
  float    qdt_2mc, cdt_dx, cdt_dy, cdt_dz, qsp, cx, cy, cz;
  int32_t  nx, ny, nz, has_neighbors;
};
static_assert(sizeof(vpic_metal_push_params) == 96, "PushParams layout changed");

// Must match SortParams in sort.metal
struct vpic_metal_sort_params {
  uint64_t np, stride, first;
};

// Must match RhoParams and EnergyParams in particle_loops.metal
struct vpic_metal_rho_params {
  uint64_t np, stride, first;
  float    q_8V;
  int32_t  sy, sz, pad;
};
static_assert(sizeof(vpic_metal_rho_params) == 40, "RhoParams layout changed");
struct vpic_metal_energy_params {
  uint64_t np, stride, first;
  float    qdt_2mc, msp;
};
static_assert(sizeof(vpic_metal_energy_params) == 32, "EnergyParams layout changed");

// Must match FieldParams in fields.metal
struct vpic_metal_field_params {
  int32_t nx, ny, nz;
  float   px, py, pz;
};
static_assert(sizeof(vpic_metal_field_params) == 24, "FieldParams layout changed");

// Host time in seconds on the clock Metal uses for command buffer timestamps
// (GPUStartTime, GPUEndTime), so host and GPU times can be compared directly.
double host_seconds() {
  static const double tick = [] {
    mach_timebase_info_data_t tb;
    mach_timebase_info(&tb);
    return 1e-9 * double(tb.numer) / double(tb.denom);
  }();
  return double(mach_absolute_time()) * tick;
}

[[noreturn]] void fail(const std::string& why) {
  fprintf(stderr, "VPIC Metal push: %s\n", why.c_str());
  fflush(stderr);
  abort();
}

// Unset or empty: fallback. "0", "false", "off" or "no": false. Else true.
bool env_flag(const char* name, bool fallback) {
  const char* v = getenv(name);
  if (!v || !*v) return fallback;
  for (const char* off : {"0", "false", "off", "no", "FALSE", "OFF", "NO"})
    if (strcmp(v, off) == 0) return false;
  return true;
}

struct Wrapped {
  id<MTLBuffer> buffer;
  NSUInteger    offset;
};

struct Context {
  id<MTLDevice>               device = nil;
  id<MTLCommandQueue>         queue = nil;
  id<MTLComputePipelineState> push = nil;
  id<MTLBuffer>               counters = nil;   // [0] movers, [1] overflow, [2] no neighbors, [3] crossers (experiment)
  id<MTLBuffer>               no_neighbors = nil;  // bound when VPIC has no neighbor table yet
  NSUInteger                  threads = 0;      // threads per threadgroup
  size_t                      chunk = 0;        // particles per command buffer
  bool                        profile = false;
  // Wrapped arrays, keyed by (data pointer, bytes). The arrays live for the
  // whole run, so the wrappers are made once and reused every step.
  std::map<std::pair<uintptr_t, size_t>, Wrapped> wrapped;
  // Totals for VPIC_METAL_PROFILE
  double   gpu_seconds = 0;
  uint64_t calls = 0, particles = 0;
  // Host-side time of the push calls (VPIC_METAL_PROFILE): from entry to
  // return, split into encoding until the last commit, waiting for the GPU
  // to start, and waking up after it finishes
  double   push_host_seconds = 0, push_encode_seconds = 0, push_start_wait_seconds = 0, push_wake_seconds = 0;

  // Sort pipelines and their scratch buffers (grown on demand, reused)
  id<MTLComputePipelineState> sort_count = nil, scan_blocks = nil, scan_add = nil, sort_scatter = nil;
  NSUInteger scan_threads = 0;   // threadgroup size of the scan kernels
  id<MTLBuffer> sort_rank = nil, sort_counts = nil, sort_p = nil, sort_cells = nil;
  std::vector<id<MTLBuffer>> scan_sums;   // block sums, one buffer per scan level
  double   sort_gpu_seconds = 0;
  uint64_t sort_calls = 0;

  // Periodic particle loops (charge deposit, energies)
  id<MTLComputePipelineState> rho = nil, energy = nil;
  id<MTLBuffer> energy_partial = nil;   // one float per SIMD group, read on the host
  double   loops_gpu_seconds = 0;
  uint64_t rho_calls = 0, energy_calls = 0;

  // Field kernels
  id<MTLComputePipelineState> advance_b = nil, load_interpolator = nil, clear_jf = nil;
  double   fields_gpu_seconds = 0;
  uint64_t field_calls = 0;
};

// Grow a scratch buffer to at least bytes (contents are not kept)
void ensure(Context& c, id<MTLBuffer> __strong& buffer, size_t bytes, const char* what) {
  if (buffer != nil && buffer.length >= bytes) return;
  buffer = [c.device newBufferWithLength:std::max<size_t>(bytes, 16) options:MTLResourceStorageModePrivate];
  if (buffer == nil) fail(std::string("could not allocate ") + std::to_string(bytes) + " bytes for " + what);
}

id<MTLComputePipelineState> pipeline(id<MTLDevice> device, id<MTLLibrary> library, NSString* name) {
  NSError* error = nil;
  id<MTLFunction> fn = [library newFunctionWithName:name];
  if (fn == nil) fail(std::string("no Metal kernel named ") + name.UTF8String);
  id<MTLComputePipelineState> p = [device newComputePipelineStateWithFunction:fn error:&error];
  if (p == nil)
    fail(std::string("building the ") + name.UTF8String + " pipeline failed: " + error.localizedDescription.UTF8String);
  return p;
}

Context* live_context = nullptr;   // set once context() has created it

Context& context() {
  static Context c = [] {
    Context c;
    c.device = MTLCreateSystemDefaultDevice();
    if (c.device == nil) fail("no Metal GPU is available");
    // Float atomics on device memory need an Apple7 (M1) or newer GPU
    if (![c.device supportsFamily:MTLGPUFamilyApple7])
      fail(std::string("GPU ") + c.device.name.UTF8String +
           " lacks the Apple7 feature set (M1 or newer) needed for float atomics");
    c.queue = [c.device newCommandQueue];

    MTLCompileOptions* options = [MTLCompileOptions new];
    // IEEE-conformant float math, so results match the CPU push to roundoff.
    // VPIC_METAL_FAST_MATH=1 relaxes it for experiments; validate before use.
    // Precise library functions too: in Safe mode Metal still uses fast
    // versions of sqrt and friends unless told otherwise.
    const bool fast = env_flag("VPIC_METAL_FAST_MATH", false);
    options.mathMode = fast ? MTLMathModeRelaxed : MTLMathModeSafe;
    options.mathFloatingPointFunctions = fast ? MTLMathFloatingPointFunctionsFast
                                              : MTLMathFloatingPointFunctionsPrecise;
    // Performance experiments: VPIC_METAL_DEFINES=NAME[,NAME...] defines
    // macros for the kernel source (see the VPIC_EXP_* blocks in
    // advance_p.metal). Results of experiment builds are not physical.
    if (const char* defs = getenv("VPIC_METAL_DEFINES"); defs && *defs) {
      NSMutableDictionary<NSString*, NSObject*>* macros = [NSMutableDictionary dictionary];
      for (NSString* name in [@(defs) componentsSeparatedByString:@","])
        if (name.length) macros[name] = @1;
      options.preprocessorMacros = macros;
      fprintf(stderr, "[vpic-metal] EXPERIMENT kernel macros: %s\n", defs);
    }
    NSError* error = nil;
    id<MTLLibrary> library =
        [c.device newLibraryWithSource:@(VPIC_METAL_SOURCE)
                               options:options
                                 error:&error];
    if (library == nil)
      fail(std::string("compiling the Metal kernels failed: ") +
           error.localizedDescription.UTF8String);
    c.push = pipeline(c.device, library, @"advance_p");
    c.sort_count = pipeline(c.device, library, @"sort_count");
    c.scan_blocks = pipeline(c.device, library, @"scan_blocks");
    c.scan_add = pipeline(c.device, library, @"scan_add");
    c.sort_scatter = pipeline(c.device, library, @"sort_scatter");
    c.rho = pipeline(c.device, library, @"accumulate_rho_p");
    c.energy = pipeline(c.device, library, @"energy_p");
    c.advance_b = pipeline(c.device, library, @"advance_b");
    c.load_interpolator = pipeline(c.device, library, @"load_interpolator");
    c.clear_jf = pipeline(c.device, library, @"clear_jf");
    // The scan kernels assume 32-wide SIMD groups and full threadgroups
    if (c.scan_blocks.threadExecutionWidth != 32)
      fail("the scan kernels need 32-wide SIMD groups; this GPU has " +
           std::to_string(c.scan_blocks.threadExecutionWidth));
    c.scan_threads = std::min<NSUInteger>(1024, c.scan_blocks.maxTotalThreadsPerThreadgroup) / 32 * 32;

    const NSUInteger width = c.push.threadExecutionWidth;
    // Threads per threadgroup for the particle kernels: 256 unless
    // VPIC_METAL_THREADS overrides it (rounded to whole SIMD groups)
    NSUInteger want = 256;
    if (const char* v = getenv("VPIC_METAL_THREADS")) {
      const long long n = atoll(v);
      if (n > 0) want = NSUInteger(n);
    }
    c.threads = std::min<NSUInteger>(want, c.push.maxTotalThreadsPerThreadgroup);
    c.threads = std::max<NSUInteger>(width, c.threads / width * width);

    c.counters = [c.device newBufferWithLength:4 * sizeof(uint32_t)
                                       options:MTLResourceStorageModeShared];
    c.no_neighbors = [c.device newBufferWithLength:6 * sizeof(int64_t)
                                           options:MTLResourceStorageModeShared];

    // Keep each command buffer short: macOS kills GPU work that stalls the
    // display. VPIC_METAL_CHUNK overrides the particles per command buffer.
    c.chunk = size_t(1) << 24;
    if (const char* v = getenv("VPIC_METAL_CHUNK")) {
      const long long n = atoll(v);
      if (n > 0) c.chunk = size_t(n);
    }
    c.profile = env_flag("VPIC_METAL_PROFILE", false);
    if (c.profile) {
      fprintf(stderr, "[vpic-metal] %s, %lu threads per threadgroup, %zu particles per command buffer, sources %.12s\n",
              c.device.name.UTF8String, (unsigned long)c.threads, c.chunk, VPIC_METAL_SOURCES_SHA256);
      // Most threads per threadgroup each kernel allows: below 1024 means its
      // register use limits how many threads the GPU keeps in flight
      for (auto [name, pso] : {std::pair<const char*, id<MTLComputePipelineState>>{"push", c.push},
                               {"sort_count", c.sort_count}, {"sort_scatter", c.sort_scatter},
                               {"accumulate_rho_p", c.rho}, {"energy_p", c.energy}, {"advance_b", c.advance_b},
                               {"load_interpolator", c.load_interpolator}})
        fprintf(stderr, "[vpic-metal]   %-18s max %4lu threads per threadgroup, SIMD width %lu\n", name,
                (unsigned long)pso.maxTotalThreadsPerThreadgroup, (unsigned long)pso.threadExecutionWidth);
      atexit([] {
        Context& c = context();
        if (c.particles) {
          fprintf(stderr, "[vpic-metal] push totals: %llu calls, %.3f s GPU, %.3f ns/particle\n",
                  (unsigned long long)c.calls, c.gpu_seconds,
                  1e9 * c.gpu_seconds / double(c.particles));
          const double per = 1e3 / double(c.calls);
          fprintf(stderr, "[vpic-metal] push host time per call: %.3f ms (GPU %.3f, encode %.3f, wait for GPU start "
                  "%.3f, wake after GPU end %.3f, other %.3f)\n", per * c.push_host_seconds, per * c.gpu_seconds,
                  per * c.push_encode_seconds, per * c.push_start_wait_seconds, per * c.push_wake_seconds,
                  per * (c.push_host_seconds - c.gpu_seconds - c.push_encode_seconds - c.push_start_wait_seconds -
                         c.push_wake_seconds));
        }
        if (c.sort_calls)
          fprintf(stderr, "[vpic-metal] sort totals: %llu calls, %.3f s GPU\n",
                  (unsigned long long)c.sort_calls, c.sort_gpu_seconds);
        if (c.field_calls)
          fprintf(stderr, "[vpic-metal] field totals: %llu calls, %.3f s GPU\n",
                  (unsigned long long)c.field_calls, c.fields_gpu_seconds);
        if (c.rho_calls + c.energy_calls)
          fprintf(stderr, "[vpic-metal] rho and energy totals: %llu + %llu calls, %.3f s GPU\n",
                  (unsigned long long)c.rho_calls, (unsigned long long)c.energy_calls, c.loops_gpu_seconds);
      });
    }
    return c;
  }();
  live_context = &c;
  return c;
}

// The Metal buffer that covers [data, data + bytes), reading and writing the
// memory in place. Metal can only wrap whole pages, so the buffer spans the
// pages around the array and the array starts at an offset into it.
Wrapped wrap(Context& c, const void* data, size_t bytes, const char* what) {
  if (data == nullptr || bytes == 0) fail(std::string(what) + " is empty");
  const auto key = std::make_pair(uintptr_t(data), bytes);
  auto it = c.wrapped.find(key);
  if (it != c.wrapped.end()) return it->second;

  const uintptr_t page = uintptr_t(getpagesize());
  const uintptr_t lo = uintptr_t(data) & ~(page - 1);
  const uintptr_t hi = (uintptr_t(data) + bytes + page - 1) & ~(page - 1);
  if (hi - lo > c.device.maxBufferLength)
    fail(std::string(what) + " needs " + std::to_string(hi - lo) +
         " bytes, more than this GPU's largest buffer (" +
         std::to_string(c.device.maxBufferLength) + " bytes)");
  id<MTLBuffer> buffer = [c.device newBufferWithBytesNoCopy:reinterpret_cast<void*>(lo)
                                                     length:hi - lo
                                                    options:MTLResourceStorageModeShared
                                                deallocator:nil];
  if (buffer == nil) fail(std::string("could not wrap ") + what + " for the GPU");
  Wrapped w{buffer, NSUInteger(uintptr_t(data) - lo)};
  c.wrapped.emplace(key, w);
  return w;
}

// Threads per threadgroup for a particle kernel: c.threads (from the push),
// capped by what this pipeline allows, in whole 32-wide SIMD groups. Kernels
// that index SIMD groups by thread position (energy_p) rely on both.
NSUInteger particle_threads(Context& c, id<MTLComputePipelineState> pso, const char* what) {
  if (pso.threadExecutionWidth != 32)
    fail(std::string("the ") + what + " kernel needs 32-wide SIMD groups; this GPU has " +
         std::to_string(pso.threadExecutionWidth));
  const NSUInteger t = std::min<NSUInteger>(c.threads, pso.maxTotalThreadsPerThreadgroup) / 32 * 32;
  if (t == 0) fail(std::string("the ") + what + " kernel allows fewer than 32 threads per threadgroup");
  return t;
}

// "vpic <what>": the label of a command buffer and its encoder, so that
// Instruments' Metal System Trace shows which kernel each one ran
NSString* label_for(const char* what) { return [NSString stringWithFormat:@"vpic %s", what]; }

// Queue a particle kernel over np particles, in command buffers of at most
// c.chunk particles (rounded down to whole SIMD groups) so that none runs long
// enough for the macOS GPU watchdog. bind(encoder, first particle, particles)
// sets the arguments for one chunk. Command buffers on one queue run in order.
template <class Bind>
void queue_particle_pass(Context& c, NSMutableArray<id<MTLCommandBuffer>>* all, id<MTLComputePipelineState> pso,
                         size_t np, const char* what, Bind bind) {
  const NSUInteger threads = particle_threads(c, pso, what);
  const size_t chunk = std::max<size_t>(32, c.chunk / 32 * 32);
  for (size_t first = 0; first < np; first += chunk) {
    const size_t n = std::min(chunk, np - first);
    id<MTLCommandBuffer> cb = [c.queue commandBuffer];
    cb.label = label_for(what);   // names the work in Instruments' Metal traces
    id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
    enc.label = cb.label;
    [enc setComputePipelineState:pso];
    bind(enc, first, n);
    [enc dispatchThreads:MTLSizeMake(n, 1, 1) threadsPerThreadgroup:MTLSizeMake(threads, 1, 1)];
    [enc endEncoding];
    [cb commit];
    [all addObject:cb];
  }
}

// Wait for the queued command buffers, abort if any failed, return the GPU time
double finish(NSMutableArray<id<MTLCommandBuffer>>* all, const char* what) {
  [all.lastObject waitUntilCompleted];
  double gpu = 0;
  for (id<MTLCommandBuffer> cb in all) {
    if (cb.status != MTLCommandBufferStatusCompleted)
      fail(std::string("a ") + what + " command buffer failed: " +
           (cb.error ? cb.error.localizedDescription.UTF8String : "unknown error"));
    gpu += cb.GPUEndTime - cb.GPUStartTime;
  }
  return gpu;
}

// Run one particle kernel and wait for it; returns the GPU time
template <class Bind>
double particle_loop(Context& c, id<MTLComputePipelineState> pso, size_t np, const char* what, Bind bind) {
  NSMutableArray<id<MTLCommandBuffer>>* all = [NSMutableArray array];
  queue_particle_pass(c, all, pso, np, what, bind);
  return finish(all, what);
}

}  // namespace

void vpic_metal_forget_arrays() {
  if (live_context == nullptr) return;   // never used the GPU
  @autoreleasepool {
    live_context->wrapped.clear();
  }
}

bool vpic_metal_push_enabled() { return env_flag("VPIC_METAL_PUSH", true); }

bool vpic_metal_push_check_enabled() { return env_flag("VPIC_METAL_PUSH_CHECK", false); }

size_t vpic_metal_advance_p(const vpic_metal_push_args& a) {
  if (a.np == 0) return 0;
  const double t_enter = host_seconds();
  @autoreleasepool {
    Context& c = context();
    if (a.max_nm > UINT32_MAX) fail("the mover list is larger than its 32-bit counter");

    const Wrapped buffers[] = {
        wrap(c, a.particles, a.particle_stride * 7 * sizeof(float), "the particles"),
        wrap(c, a.particles_i, a.particle_capacity * sizeof(int), "the particle cells"),
        wrap(c, a.interpolators, a.nvoxels * 18 * sizeof(float), "the interpolators"),
        wrap(c, a.fields, a.nvoxels * 16 * sizeof(float), "the fields"),
        a.neighbors ? wrap(c, a.neighbors, a.nvoxels * 6 * sizeof(int64_t), "the neighbor table")
                    : Wrapped{c.no_neighbors, 0},
        wrap(c, a.movers, a.max_nm * 3 * sizeof(float), "the movers"),
        wrap(c, a.movers_i, a.max_nm * sizeof(size_t), "the mover indices"),
        wrap(c, a.copies, a.max_nm * 7 * sizeof(float), "the mover copies"),
        wrap(c, a.copies_i, a.max_nm * sizeof(int), "the mover copy cells"),
    };
    uint32_t* counters = static_cast<uint32_t*>(c.counters.contents);
    counters[0] = 0;
    counters[1] = 0;
    counters[2] = 0;
    counters[3] = 0;

    vpic_metal_push_params P{};
    P.np = a.np;
    P.stride = a.particle_stride;
    P.max_nm = a.max_nm;
    P.rangel = a.rangel;
    P.rangeh = a.rangeh;
    P.qdt_2mc = a.qdt_2mc; P.cdt_dx = a.cdt_dx; P.cdt_dy = a.cdt_dy; P.cdt_dz = a.cdt_dz;
    P.qsp = a.qsp; P.cx = a.cx; P.cy = a.cy; P.cz = a.cz;
    P.nx = a.nx; P.ny = a.ny; P.nz = a.nz;
    P.has_neighbors = a.neighbors != nullptr;

    // One command buffer per chunk of particles, all queued before waiting;
    // the mover counter carries over between them.
    NSMutableArray<id<MTLCommandBuffer>>* all = [NSMutableArray array];
    queue_particle_pass(c, all, c.push, a.np, "push", [&](id<MTLComputeCommandEncoder> enc, size_t first, size_t) {
      P.first = first;
      for (NSUInteger k = 0; k < 9; ++k)
        [enc setBuffer:buffers[k].buffer offset:buffers[k].offset atIndex:k];
      [enc setBuffer:c.counters offset:0 atIndex:9];
      [enc setBytes:&P length:sizeof(P) atIndex:10];
    });
    const double t_committed = host_seconds();
    const double gpu = finish(all, "push");
    const double t_done = host_seconds();
    if (counters[1]) fail("the mover list overflowed (max_nm too small for this species)");
    if (counters[2])
      fail("a particle left its cell before VPIC built the grid's neighbor table "
           "(advance_p called during deck initialisation?)");

    c.gpu_seconds += gpu;
    c.calls += 1;
    c.particles += a.np;
    const double start_wait = std::max(0.0, all.firstObject.GPUStartTime - t_committed);
    const double wake = std::max(0.0, t_done - all.lastObject.GPUEndTime);
    c.push_host_seconds += t_done - t_enter;
    c.push_encode_seconds += t_committed - t_enter;
    c.push_start_wait_seconds += start_wait;
    c.push_wake_seconds += wake;
    if (c.profile)
      fprintf(stderr, "[vpic-metal] push %zu particles in %lu command buffer(s): %.3f ms GPU, %.3f ns/particle, %u movers, %u crossers; "
              "host %.3f ms (encode %.3f, wait for start %.3f, wake %.3f)\n",
              a.np, (unsigned long)all.count, 1e3 * gpu, 1e9 * gpu / double(a.np), counters[0], counters[3],
              1e3 * (t_done - t_enter), 1e3 * (t_committed - t_enter), 1e3 * start_wait, 1e3 * wake);
    return counters[0];
  }
}

bool vpic_metal_sort_enabled() { return env_flag("VPIC_METAL_SORT", true); }

bool vpic_metal_sort_check_enabled() { return env_flag("VPIC_METAL_SORT_CHECK", false); }

void vpic_metal_sort_particles(const vpic_metal_sort_args& a) {
  if (a.np == 0) return;
  if (a.np > UINT32_MAX || a.ncells > UINT32_MAX)
    fail("the GPU sort counts particles and cells with 32-bit integers");
  @autoreleasepool {
    Context& c = context();
    const Wrapped p = wrap(c, a.particles, a.particle_stride * 7 * sizeof(float), "the particles");
    const Wrapped cells = wrap(c, a.particles_i, a.particle_capacity * sizeof(int), "the particle cells");
    ensure(c, c.sort_rank, a.np * sizeof(uint32_t), "the sort ranks");
    ensure(c, c.sort_counts, a.ncells * sizeof(uint32_t), "the cell counts");
    ensure(c, c.sort_p, a.particle_stride * 7 * sizeof(float), "the sort scratch particles");
    ensure(c, c.sort_cells, a.np * sizeof(int), "the sort scratch cells");

    // Scan levels: level 0 scans the cell counts, level k+1 the block sums of level k
    const NSUInteger tg = c.scan_threads;
    std::vector<uint32_t> level_n{uint32_t(a.ncells)};
    while (level_n.back() > tg) level_n.push_back(uint32_t((level_n.back() + tg - 1) / tg));
    if (c.scan_sums.size() < level_n.size()) c.scan_sums.resize(level_n.size());
    for (size_t l = 0; l < level_n.size(); ++l) {
      const size_t blocks = (level_n[l] + tg - 1) / tg;
      ensure(c, c.scan_sums[l], blocks * sizeof(uint32_t), "the scan block sums");
    }
    auto level_data = [&](size_t l) { return l == 0 ? c.sort_counts : c.scan_sums[l - 1]; };

    // Command buffers on one queue run in order. The particle passes go in
    // chunks of at most c.chunk particles per command buffer, like the push,
    // so that no command buffer runs long enough for the macOS GPU watchdog.
    NSMutableArray<id<MTLCommandBuffer>>* all = [NSMutableArray array];
    auto commit = [&](id<MTLCommandBuffer> cb) { [cb commit]; [all addObject:cb]; };
    auto particle_pass = [&](id<MTLComputePipelineState> pso, const char* what, auto bind) {
      queue_particle_pass(c, all, pso, a.np, what, [&](id<MTLComputeCommandEncoder> enc, size_t first, size_t) {
        bind(enc, vpic_metal_sort_params{a.np, a.particle_stride, first});
      });
    };

    // 1. Clear the counts, then count particles per cell (with their ranks)
    {
      id<MTLCommandBuffer> cb = [c.queue commandBuffer];
      cb.label = label_for("sort clear");
      id<MTLBlitCommandEncoder> clear = [cb blitCommandEncoder];
      [clear fillBuffer:c.sort_counts range:NSMakeRange(0, a.ncells * sizeof(uint32_t)) value:0];
      [clear endEncoding];
      commit(cb);
    }
    particle_pass(c.sort_count, "sort count", [&](id<MTLComputeCommandEncoder> enc, const vpic_metal_sort_params& S) {
      [enc setBuffer:cells.buffer offset:cells.offset atIndex:0];
      [enc setBuffer:c.sort_counts offset:0 atIndex:1];
      [enc setBuffer:c.sort_rank offset:0 atIndex:2];
      [enc setBytes:&S length:sizeof(S) atIndex:3];
    });

    // 2. Exclusive prefix sum of the counts: each cell's first slot. Dispatches
    // in one (serial) compute encoder run in order, each seeing the previous
    // one's writes. This touches cells, not particles, so it is short.
    {
      id<MTLCommandBuffer> cb = [c.queue commandBuffer];
      cb.label = label_for("sort scan");
      id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
      enc.label = cb.label;
      [enc setComputePipelineState:c.scan_blocks];
      [enc setThreadgroupMemoryLength:32 * sizeof(uint32_t) atIndex:0];
      for (size_t l = 0; l < level_n.size(); ++l) {
        const uint32_t n = level_n[l];
        [enc setBuffer:level_data(l) offset:0 atIndex:0];
        [enc setBuffer:c.scan_sums[l] offset:0 atIndex:1];
        [enc setBytes:&n length:sizeof(n) atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake((n + tg - 1) / tg, 1, 1) threadsPerThreadgroup:MTLSizeMake(tg, 1, 1)];
      }
      [enc setComputePipelineState:c.scan_add];
      for (size_t l = level_n.size() - 1; l-- > 0;) {
        const uint32_t n = level_n[l];
        [enc setBuffer:level_data(l) offset:0 atIndex:0];
        [enc setBuffer:c.scan_sums[l] offset:0 atIndex:1];
        [enc setBytes:&n length:sizeof(n) atIndex:2];
        [enc dispatchThreadgroups:MTLSizeMake((n + tg - 1) / tg, 1, 1) threadsPerThreadgroup:MTLSizeMake(tg, 1, 1)];
      }
      [enc endEncoding];
      commit(cb);
    }

    // 3. Scatter each particle to its slot in the scratch arrays
    particle_pass(c.sort_scatter, "sort scatter", [&](id<MTLComputeCommandEncoder> enc, const vpic_metal_sort_params& S) {
      [enc setBuffer:p.buffer offset:p.offset atIndex:0];
      [enc setBuffer:cells.buffer offset:cells.offset atIndex:1];
      [enc setBuffer:c.sort_counts offset:0 atIndex:2];
      [enc setBuffer:c.sort_rank offset:0 atIndex:3];
      [enc setBuffer:c.sort_p offset:0 atIndex:4];
      [enc setBuffer:c.sort_cells offset:0 atIndex:5];
      [enc setBytes:&S length:sizeof(S) atIndex:6];
    });

    // 4. Copy the sorted particles back over the originals, column by column
    const NSUInteger column = a.particle_stride * sizeof(float);
    const size_t chunk = std::max<size_t>(32, c.chunk / 32 * 32);
    for (size_t first = 0; first < a.np; first += chunk) {
      const size_t n = std::min(chunk, a.np - first);
      id<MTLCommandBuffer> cb = [c.queue commandBuffer];
      cb.label = label_for("sort copy back");
      id<MTLBlitCommandEncoder> back = [cb blitCommandEncoder];
      for (NSUInteger v = 0; v < 7; ++v)
        [back copyFromBuffer:c.sort_p sourceOffset:v * column + first * sizeof(float) toBuffer:p.buffer
           destinationOffset:p.offset + v * column + first * sizeof(float) size:n * sizeof(float)];
      [back copyFromBuffer:c.sort_cells sourceOffset:first * sizeof(int) toBuffer:cells.buffer
         destinationOffset:cells.offset + first * sizeof(int) size:n * sizeof(int)];
      [back endEncoding];
      commit(cb);
    }

    const double gpu = finish(all, "sort");
    c.sort_gpu_seconds += gpu;
    c.sort_calls += 1;
    if (c.profile)
      fprintf(stderr, "[vpic-metal] sort %zu particles over %zu cells: %.3f ms GPU (%zu scan levels)\n", a.np,
              a.ncells, 1e3 * gpu, level_n.size());
  }
}

bool vpic_metal_particle_loops_enabled() { return env_flag("VPIC_METAL_PARTICLE_LOOPS", true); }

bool vpic_metal_particle_loops_check_enabled() { return env_flag("VPIC_METAL_PARTICLE_LOOPS_CHECK", false); }

void vpic_metal_accumulate_rho_p(const vpic_metal_rho_args& a) {
  if (a.np == 0) return;
  @autoreleasepool {
    Context& c = context();
    const Wrapped p = wrap(c, a.particles, a.particle_stride * 7 * sizeof(float), "the particles");
    const Wrapped cells = wrap(c, a.particles_i, a.particle_capacity * sizeof(int), "the particle cells");
    const Wrapped f = wrap(c, a.fields, a.nvoxels * 16 * sizeof(float), "the fields");
    const double gpu = particle_loop(c, c.rho, a.np, "charge deposit",
                                     [&](id<MTLComputeCommandEncoder> enc, size_t first, size_t) {
      const vpic_metal_rho_params R{a.np, a.particle_stride, first, a.q_8V, a.sy, a.sz, 0};
      [enc setBuffer:p.buffer offset:p.offset atIndex:0];
      [enc setBuffer:cells.buffer offset:cells.offset atIndex:1];
      [enc setBuffer:f.buffer offset:f.offset atIndex:2];
      [enc setBytes:&R length:sizeof(R) atIndex:3];
    });
    c.loops_gpu_seconds += gpu;
    c.rho_calls += 1;
    if (c.profile)
      fprintf(stderr, "[vpic-metal] charge deposit %zu particles: %.3f ms GPU, %.3f ns/particle\n", a.np, 1e3 * gpu,
              1e9 * gpu / double(a.np));
  }
}

double vpic_metal_energy_p(const vpic_metal_energy_args& a) {
  if (a.np == 0) return 0;
  @autoreleasepool {
    Context& c = context();
    const Wrapped p = wrap(c, a.particles, a.particle_stride * 7 * sizeof(float), "the particles");
    const Wrapped cells = wrap(c, a.particles_i, a.particle_capacity * sizeof(int), "the particle cells");
    const Wrapped ia = wrap(c, a.interpolators, a.nvoxels * 18 * sizeof(float), "the interpolators");
    // One partial sum per SIMD group; chunks are whole SIMD groups, so a
    // chunk starting at particle first writes from partial first/32 on
    const size_t groups = (a.np + 31) / 32;
    if (c.energy_partial == nil || c.energy_partial.length < groups * sizeof(float)) {
      c.energy_partial = [c.device newBufferWithLength:groups * sizeof(float) options:MTLResourceStorageModeShared];
      if (c.energy_partial == nil) fail("could not allocate the energy partial sums");
    }
    const double gpu = particle_loop(c, c.energy, a.np, "energy",
                                     [&](id<MTLComputeCommandEncoder> enc, size_t first, size_t) {
      const vpic_metal_energy_params E{a.np, a.particle_stride, first, a.qdt_2mc, a.msp};
      [enc setBuffer:p.buffer offset:p.offset atIndex:0];
      [enc setBuffer:cells.buffer offset:cells.offset atIndex:1];
      [enc setBuffer:ia.buffer offset:ia.offset atIndex:2];
      [enc setBuffer:c.energy_partial offset:first / 32 * sizeof(float) atIndex:3];
      [enc setBytes:&E length:sizeof(E) atIndex:4];
    });
    const float* partial = static_cast<const float*>(c.energy_partial.contents);
    double en = 0;
    for (size_t k = 0; k < groups; ++k) en += double(partial[k]);
    c.loops_gpu_seconds += gpu;
    c.energy_calls += 1;
    if (c.profile)
      fprintf(stderr, "[vpic-metal] energy %zu particles: %.3f ms GPU\n", a.np, 1e3 * gpu);
    return en;
  }
}

// Off by default: on a base M4 these kernels are no faster than the CPU (see metal_push.h)
bool vpic_metal_fields_enabled() { return env_flag("VPIC_METAL_FIELDS", false); }

bool vpic_metal_fields_check_enabled() { return env_flag("VPIC_METAL_FIELDS_CHECK", false); }

namespace {

// Run one grid kernel over (nx, ny, nz) threads (x fastest) and wait for it.
// Field kernels touch each voxel once and finish in milliseconds, so one
// command buffer is well within the macOS GPU watchdog.
template <class Bind>
void field_kernel(Context& c, id<MTLComputePipelineState> pso, MTLSize grid, const char* what, Bind bind) {
  if (grid.width == 0 || grid.height == 0 || grid.depth == 0) return;
  NSMutableArray<id<MTLCommandBuffer>>* all = [NSMutableArray array];
  id<MTLCommandBuffer> cb = [c.queue commandBuffer];
  cb.label = label_for(what);
  id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
  enc.label = cb.label;
  [enc setComputePipelineState:pso];
  bind(enc);
  // Threadgroups of up to 64 x 4 threads: x (contiguous voxels) first, then y
  const NSUInteger tx = std::min<NSUInteger>({NSUInteger(64), grid.width, pso.maxTotalThreadsPerThreadgroup});
  const NSUInteger ty = std::min<NSUInteger>({NSUInteger(4), grid.height, pso.maxTotalThreadsPerThreadgroup / tx});
  [enc dispatchThreads:grid threadsPerThreadgroup:MTLSizeMake(tx, ty, 1)];
  [enc endEncoding];
  [cb commit];
  [all addObject:cb];
  const double gpu = finish(all, what);
  c.fields_gpu_seconds += gpu;
  c.field_calls += 1;
  if (c.profile) fprintf(stderr, "[vpic-metal] %s: %.3f ms GPU\n", what, 1e3 * gpu);
}

}  // namespace

void vpic_metal_advance_b(const vpic_metal_field_args& a) {
  @autoreleasepool {
    Context& c = context();
    const Wrapped f = wrap(c, a.fields, a.nvoxels * 16 * sizeof(float), "the fields");
    const vpic_metal_field_params G{a.nx, a.ny, a.nz, a.px, a.py, a.pz};
    field_kernel(c, c.advance_b, MTLSizeMake(a.nx + 1, a.ny + 1, a.nz + 1), "advance_b",
                 [&](id<MTLComputeCommandEncoder> enc) {
      [enc setBuffer:f.buffer offset:f.offset atIndex:0];
      [enc setBytes:&G length:sizeof(G) atIndex:1];
    });
  }
}

void vpic_metal_load_interpolator(const vpic_metal_field_args& a) {
  @autoreleasepool {
    Context& c = context();
    const Wrapped f = wrap(c, a.fields, a.nvoxels * 16 * sizeof(float), "the fields");
    const Wrapped ia = wrap(c, a.interpolators, a.nvoxels * 18 * sizeof(float), "the interpolators");
    const vpic_metal_field_params G{a.nx, a.ny, a.nz, 0, 0, 0};
    field_kernel(c, c.load_interpolator, MTLSizeMake(a.nx, a.ny, a.nz), "load_interpolator",
                 [&](id<MTLComputeCommandEncoder> enc) {
      [enc setBuffer:ia.buffer offset:ia.offset atIndex:0];
      [enc setBuffer:f.buffer offset:f.offset atIndex:1];
      [enc setBytes:&G length:sizeof(G) atIndex:2];
    });
  }
}

void vpic_metal_clear_jf(const vpic_metal_field_args& a) {
  if (a.nvoxels > UINT32_MAX) fail("clear_jf counts voxels with 32-bit integers");
  @autoreleasepool {
    Context& c = context();
    const Wrapped f = wrap(c, a.fields, a.nvoxels * 16 * sizeof(float), "the fields");
    const uint32_t nv = uint32_t(a.nvoxels);
    field_kernel(c, c.clear_jf, MTLSizeMake(a.nvoxels, 1, 1), "clear_jf", [&](id<MTLComputeCommandEncoder> enc) {
      [enc setBuffer:f.buffer offset:f.offset atIndex:0];
      [enc setBytes:&nv length:sizeof(nv) atIndex:1];
    });
  }
}
